// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSumVal) public {
        minSumVal = bound(minSumVal, 1, type(uint256).max);
        c.SetMinSum(minSumVal);
        c.Initialized();
        // After initialization, MinSum should equal the value we set
        assertTrue(c.MinSum() == minSumVal);
    }
}

